    #define BUFSIZE 16384

    typedef struct node {
    	int element[BUFSIZE];
    	int size;
    	int current;
    }Stack;

    static Stack *stack;
    static int level;
    static int integer;

    bool initialize(void) {
    	if (stack == NULL)
    		stack = (Stack *)malloc(sizeof(Stack));

    	stack->size = BUFSIZE;
    	stack->current = 0;
    	return true;
    }

    bool push(int number) {
    	if (stack == NULL)
    		return false;
    	if ((stack->current + 1) > stack->size)
    		return false;

    	stack->element[stack->current] = number;
    	stack->current++;
    	return true;
    }

    int pop() {
    	if (stack->current <= 0)
    		return 0xFFFFFFFF;
    	stack->current--;
    	return stack->element[stack->current];
    }

    int sum() {
    	int result = 0;
    	int i;
    	if (stack == NULL)
    		return 0xFFFFFFFF;
    	if (stack->current == 0)
    		return 0xFFFFFFFF;

    	for (i = 0; i < stack->current; i++)
    		result += stack->element[i];

    	return result;
    }

    void replace(char * o_string, char * s_string, char * r_string) {
