		bool LoadRecongizer(String^ DllPath)
		{
			HInstance = ::LoadLibrary(msclr::interop::marshal_as<std::wstring>(DllPath).c_str());
			if (HInstance == nullptr) return false;
			if (!LoadFunctions())	return false;
			return true;
