    import android.database.sqlite.SQLiteDatabase;
    import android.database.sqlite.SQLiteOpenHelper;
    import android.util.Log;

    import java.util.ArrayList;
    import java.util.HashMap;

    public class myDBClass extends SQLiteOpenHelper {


        // Database Version
        private static final int DATABASE_VERSION = 1;

        // Database Name
        private static final String DATABASE_NAME = "mydatabase";

        // Table Name
        private static final String TABLE_MEMBER = "members";

        public myDBClass(Context context) {
            super(context, DATABASE_NAME, null, DATABASE_VERSION);
            // TODO Auto-generated constructor stub
        }

        @Override
        public void onCreate(SQLiteDatabase db) {
            // TODO Auto-generated method stub
            // Create Table Name
            db.execSQL("CREATE TABLE " + TABLE_MEMBER +
                    "(MemberID INTEGER PRIMARY KEY AUTOINCREMENT," +
                    " Name TEXT(100)," +
                    " Tel TEXT(100));");

            Log.d("CREATE TABLE", "Create Table Successfully.");
        }


        // Select Data
        public String[] SelectData(String strMemberID) {
            // TODO Auto-generated method stub

            try {
                String arrData[] = null;

                SQLiteDatabase db;
                db = this.getReadableDatabase(); // Read Data

                Cursor cursor = db.query(TABLE_MEMBER, new String[]{"*"},
                        "MemberID=?",
                        new String[]{String.valueOf(strMemberID)}, null, null, null, null);

                if(cursor != null)
                {
                    if (cursor.moveToFirst()) {
                        arrData = new String[cursor.getColumnCount()];
                        /***
                         *  0 = MemberID
                         *  1 = Name
                         *  2 = Tel
                         */
                        arrData[0] = cursor.getString(0);
                        arrData[1] = cursor.getString(1);
                        arrData[2] = cursor.getString(2);
                    }
                }
                cursor.close();
                db.close();
                return arrData;

            } catch (Exception e) {
                return null;
            }

        }

        // Show All Data
        public ArrayList<HashMap<String, String>> SelectAllData() {
            // TODO Auto-generated method stub

            try {

                ArrayList<HashMap<String, String>> MyArrList = new ArrayList<>();
                HashMap<String, String> map;

                SQLiteDatabase db;
                db = this.getReadableDatabase(); // Read Data

                String strSQL = "SELECT  * FROM " + TABLE_MEMBER;
                Cursor cursor = db.rawQuery(strSQL, null);

                if(cursor != null)
                {
                    if (cursor.moveToFirst()) {
                        do {
                            map = new HashMap<>();
                            map.put("MemberID", cursor.getString(0));
                            map.put("Name", cursor.getString(1));
                            map.put("Tel", cursor.getString(2));
                            MyArrList.add(map);
                        } while (cursor.moveToNext());
                    }
                }
                cursor.close();
                db.close();
                return MyArrList;

            } catch (Exception e) {
                return null;
            }

        }



        @Override
        public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
            // TODO Auto-generated method stub
            db.execSQL("DROP TABLE IF EXISTS " + TABLE_MEMBER);

            // Re Create on method  onCreate
            onCreate(db);
        }


    }

