        //Convert String to CharArray 

        char[] charArray = input.toCharArray();            
//array tests characters
        StringBuffer buffer = new StringBuffer(input.length());              //stringbuffer so it can modified as needed

        int totalCorrect = 0;     
>>//created totalCorrect variable to help program end at the right time

        for (int i = 0; i < input.length(); i++)         
>>//buffer can be used as long as int is less than total length of word
          buffer.append('_');

        while (NotFullMan)
         {
         System.out.println("Enter a letter");
         guessedLetter = hm.nextLine().charAt(0);     
//starts game, player must guess a letter
         int correct = 0;

         for ( int i=0; i < charArray.length; i++)
           {                //Checks each letter
            if(guessedLetter == charArray[i] && buffer.charAt(i) == '_')
