          if (totalCorrect == input.length())    >   //ends when totalCorrect is equal to the number of characters in word
             return;

        }
        }
     }

    module make_counter(h, clk, P);
        input wire h;
        input wire clk;
        output wire P;
        reg r=1'b1;
        reg[9:0] n=0;

        always @(negedge clk)
              always @(posedge h)
              begin 
                  n=0;
              end

              begin
              if(n<600)
                    n=n+1'b1;

              if(n==106)
                    r<=1'b0;
              else if(n==517)
                    r<=1'b1;
              else 
                    ;
              end
        assign P=r;
    endmodule

