    const double PI = 3.1415926;

    class Circle
    {
    public:
	    Circle();
	    double AreaP(int r);
	    double PerimeterP(int r);
	    ~Circle();


    private:
	    int R;
    	int PoF;
    	int PoR;
    };

    double Circle::AreaP(int r)
    {
	    return ((r + R)*(r + R) - r*r)*PI*PoR;
    }

    double Circle::PerimeterP(int r)
    {
	    return (r + R) * 2 * PI*PoF;
    }

    Circle::Circle()
    {
    	int R = 3;
    	int PoF = 35;
    	int PoR = 20;
