def Partition2(a,low,high):
    key = a[low]
    while low < high:
        while low < high and a[high] >= key:
            high -= 1
        while low < high and a[high] < key:
            a[low] = a[high]
            low += 1
            a[high] = a[low]
    a[low] = key
    return low

