    template<typename T>
    class Queue{

      private : enum{
        SIZE=9
      };
      private : T* commandArray[SIZE];
      private : int m_added = 0, m_removed = 0;

      public : void enqueue(T* t){

            commandArray[m_added] = t;
            m_added = (m_added + 1) % SIZE;
        }
      public : T* dequeue(){
            int temp = m_removed;
            m_removed = (m_removed + 1) % SIZE;
            return commandArray[temp];
        }
    };
