		{
			int lo = 0;
			int hi = arr_size - 1;
			int mid = 0,temp=0;
			int h2=arr_size - 1;
			while (mid <= hi)
			{
				switch (a[mid])
				{
				case 0:
				{
					temp = a[lo];
					a[lo] = a[mid];
					a[mid] = temp;
					lo++;
					mid++;
					break;
				}
				case 1:
					mid++;
					break;
				case 2:
				{
					temp = a[mid];
					a[mid] = a[hi];
					a[hi] = temp;

					hi--;
					h2=hi;
					break;
				}
				case 3:{
					temp = a[mid];
					a[mid] = a[h2];
					a[h2] = temp;
