    import java.util.Scanner;

    public class PascalsTriangle {

	private int lineNumber,count;
	private int[] num;

	public PascalsTriangle()
	{
		lineNumber = 1;
	}

	public PascalsTriangle(int n)
	{
		set(n);
	}

	public void set(int n)
	{
		if (n<1)
		lineNumber = n;
	}

	public int get()
	{
		return lineNumber;
	}

	private void pascal(int[] row)
	{
		if (count >= lineNumber)
			return;
		num = new int [row.length+1];
		num[0] = 1;

		for (int i=1; i<row.length; i++)
			num[i] = row[i-1] + row[i];
		num[row.length] = 1;
		count++;
		pascal(num);
		return;
	}

	public int[] output()
	{
		count = 1;
		num = new int[count];
		return num;
	}

	public static void main(String[] args) {
		{
			int i,num;

			Scanner scan = new Scanner (System.in);
			System.out.println("Enter the Nth number: ");

			num = scan.nextInt();
			PascalsTriangle t = new PascalsTriangle(num);
			int[] result = t.output();
			System.out.println("Line" + t.get());
			for(i=0;< result.length;i++)
			System.out.println(result[i] + " ");;


		}


	}

 }


