    	public int gettotalCorrect()
    	{
    		int k = 0;
    		for (int i = 0; i < stuAnswer.length; i++)
    		{
    			if (stuAnswer[i] == answer[i])
    				totalCorrect++;
    		}
    		return totalCorrect;
    	}

    	public int gettotalIncorrect()
    	{
    		return 20-totalCorrect;
    	}

    	public int[] getMissed()
    	{
    		int k = 0;
    		for (int i = 0; i < stuAnswer.length; i++)
    		{
    			if (stuAnswer[i] != answer[i])
    			{
    				missed[k] = i;
    				k++;
    			}
    		}
    		return missed;
    	}
    }

