    	// Query parameters are parameters:
    	// http://localhost/<appln-folder-name>/register/doregister?name=pqrs&username=abc&password=xyz
    	public String doLogin(String json)  {
    		JSONObject jsonobject = new JSONObject(json);
    		System.out.println(jsonobject);
    		String name=(String) jsonobject.get("name");
    		String uname=(String) jsonobject.get("username");
    		String pwd=(String) jsonobject.get("password");
    		String response = "";
    		System.out.println("name"+name);
    		System.out.println("username"+uname);
    		System.out.println("password"+pwd);
    		int retCode = registerUser(name, uname, pwd);
    		if (retCode == 0) {
    			response = Utility.constructJSON("register", "Successfully Registered");
    		} else if (retCode == 1) {
    			response = Utility.constructJSON("register", "You are already registered");
    		} else if (retCode == 2) {
    			response = Utility.constructJSON("register", 
    					"Special Characters are not allowed in Username and Password");
    		} else if (retCode == 3) {
    			response = Utility.constructJSON("register", "Error occured");
    		}
    		return response;

    	}

    	private int registerUser(String name, String uname, String pwd) {
    		System.out.println("Credentials are correct");
    		int result = 3;

    		if (Utility.isNotNull(uname) && Utility.isNotNull(pwd)) {
    			try {
    				if (DbConnection.insertUser(name, uname, pwd)) {
    					System.out.println("User Registered");
    					result = 0;
    				}
    			} catch (SQLException sqle) {
    				System.out.println("U are already Registered");

    				if (sqle.getErrorCode() == 1062) {
    					result = 1;
    				}

    				else if (sqle.getErrorCode() == 1064) {
    					System.out.println(sqle.getErrorCode());
    					result = 2;
    				}
    			} catch (Exception e) {
    				// TODO Auto-generated catch block
    				System.out.println("Inside checkCredentials catch e ");
    				result = 3;
    			}
    		} else {
    			System.out.println("Inside checkCredentials else");
    			result = 3;
    		}

    		return result;
    	}

