            super.onStart();

            databaseBooks.addValueEventListener(new ValueEventListener() {
                @Override
                public void onDataChange(DataSnapshot dataSnapshot) {

                    bookList.clear();

                    for (DataSnapshot bookSnapshot : dataSnapshot.getChildren()){
