    #! python3
# Hello World program in Python
# Hello World program in Python

class Noddy:
    def __init__(self, x):
        self.ant = None
        self.dec = None
        self.holder = x

    @classmethod
    def make(self, l):
        ent = Noddy(l.pop(0))
        for x in l:
            ent.scrobble(x)
        return ent

    def scrobble(self, x):
        if self.holder > x:
            if self.ant is None:
                self.ant = Noddy(x)
            else:
                self.ant.scrobble(x)
        else:
            if self.dec is None:
                self.dec = Noddy(x)
            else:
                self.dec.scrobble(x)

    def bubble(self):
        if self.ant:
            for x in self.ant.bubble():
                yield x
            yield self.holder
            if self.dec:
                for x in self.dec.bubble():
                    yield x

    def bobble(self):
        yield self.holder
        if self.ant:
            for x in self.ant.bobble():
                yield x
        if self.dec:
            for x in self.dec.bobble():
                yield x

    def main():
