    char *my_getline(FILE *stream) {
        char *line = NULL;
        size_t pos = 0;
        int c;

        while ((c = getc(stream)) != EOF) {
            char *newp = realloc(line, pos + 2);
            if (newp == NULL) {
                free(line);
                return NULL;
            }
            line = newp;
            if (c == '\n')
                break;
            line[pos++] = (char)c;
