    		this.capacity=capacity;
    		data = new Object[capacity];
    	}

    	public boolean isEmpty(){
    		return(idx_top<0);

    	}
    	public boolean isFull(){
    		return(idx_top>=capacity-1);
    	}

    	public int size()
    	{
